import json
from pathlib import Path

def load_json(path: str | Path):
    file_path = Path(path)
    try:
        with file_path.open("r", encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"找不到 JSON 檔案：{file_path}") from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f"JSON 格式錯誤：{file_path}:{exc.lineno}:{exc.colno}") from exc

export function groupBy<T, K>(items: readonly T[], keyOf: (item: T) => K): Map<K, T[]> {
  const groups = new Map<K, T[]>();
  for (const item of items) {
    const key = keyOf(item);
    const group = groups.get(key);
    if (group) group.push(item);
    else groups.set(key, [item]);
  }
  return groups;
}

use std::{fs, io, path::Path};

fn read_text(path: &Path) -> Result<String, io::Error> {
    fs::read_to_string(path).map_err(|err| {
        io::Error::new(err.kind(), format!("failed to read {}: {err}", path.display()))
    })
}
